export const getSubmitCareerApplicationUrl = (tenantCode: string, id: string) => {
  return `/api/public/${tenantCode}/careers/openings/${id}/applications`;
};

/**
 * @summary Apply with a multipart form: the application as JSON in 'application', the CV in 'cv' (PDF or DOCX, at most 5 MB)
 */
export const submitCareerApplication = async (
  tenantCode: string,
  id: string,
  submitCareerApplicationBody: SubmitCareerApplicationBody,
  options?: Parameters<typeof customFetch>[1],
): Promise<void> => {
  const formData = new FormData();
  if (submitCareerApplicationBody.application !== undefined) {
    formData.append(`application`, submitCareerApplicationBody.application);
  }

  if (submitCareerApplicationBody.cv !== undefined) {
    formData.append(`cv`, submitCareerApplicationBody.cv);
  }

  return customFetch<void>(getSubmitCareerApplicationUrl(tenantCode, id), {
    ...options,
    method: 'POST',
    body: formData,
  });
};

